`Term::read_key()`:
```rust
pub fn read_key(&self) -> io::Result<Key> {
    if !self.is_tty {
        Ok(Key::Unknown)  // Returns Unknown if not a TTY
    } else {
        read_single_key(false)  // Reads from the actual TTY
    }
}
