        );
        assert_eq!(eof_default(&prompt).as_string(), "x");
    }

    #[test]
    fn eof_default_multiselect_uses_default() {
        let options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
                value: "b".to_string(),
